def gw_restart(**env):
    subprocess.run("pkill -f '[g]ateway.py'",shell=True); time.sleep(1.5)
    subprocess.Popen(['python3','/tmp/gateway.py','3005'],env=dict(os.environ,**env),stdout=open('/tmp/gw.log','w'),stderr=subprocess.STDOUT,start_new_session=True)
    for _ in range(20):
        try: urllib.request.urlopen(GW+'/auth/v1/user')
        except urllib.error.HTTPError: return
        except Exception: time.sleep(0.5)
def objs(): return json.loads(urllib.request.urlopen(GW+'/_objects').read())
def title(h): m=re.search(r'<title>(.*?)</title>',h,re.S); return m.group(1) if m else ''
